let saved={};try{saved=JSON.parse(localStorage.getItem('accountingLab.v1')||'{}');}catch{}
let state={studio:'sql',dataset:'songs',index:0,play:false,completed:new Set(saved.completed||[]),drafts:saved.drafts||{},last:null,worker:null,timer:null,working:false,data:null,loadId:0};
const dataCache={};const fmt=new Intl.NumberFormat('da-DK',{maximumFractionDigits:8});
const same=(a,b)=>typeof a==='number'&&typeof b==='number'?Math.abs(a-b)<=1e-7*Math.max(1,Math.abs(a),Math.abs(b)):a===b;
function persist(){try{localStorage.setItem('accountingLab.v1',JSON.stringify({completed:[...state.completed],drafts:state.drafts}));}catch{}}
function current(){return state.play?null:exercises[state.dataset][state.index];}
function key(){return state.dataset+':'+(state.play?'play':current().id);}
function input(){return state.studio==='sql'?$('sqlInput'):$('formulaInput');}
function remember(){if(state.working)return;state.drafts[key()]={text:input().value,mode:$('formulaMode').value};persist();}
function stop(){if(state.worker)state.worker.terminate();clearTimeout(state.timer);state.worker=null;state.working=false;$('runButton').disabled=false;$('checkButton').disabled=state.play;$('runButton').innerHTML=state.studio==='sql'?'<span>▶</span> Kør SQL <kbd>⌘ ↵</kbd>':'<span>▶</span> Beregn <kbd>⌘ ↵</kbd>';}
function clearResults(){state.last=null;$('resultCount').textContent='Klar til dit næste forsøg';$('timing').textContent='';$('feedback').hidden=true;$('tableFooter').hidden=true;$('exportButton').disabled=true;$('resultArea').replaceChildren();const div=document.createElement('div');div.className='empty-result';div.innerHTML='<span class="empty-icon">▤<span>↗</span></span><h3>Her lander dit næste aha.</h3><p>Skriv din løsning, og tryk <strong>'+(state.studio==='sql'?'Kør SQL':'Beregn')+'</strong>.<br>Dit resultat vises her — du kan altid prøve igen.</p>';$('resultArea').append(div);}
function feedback(message,type='neutral'){$('feedback').textContent=message;$('feedback').className='feedback '+type;$('feedback').hidden=false;}
function list(){
 $('exerciseList').replaceChildren();const items=exercises[state.dataset];let completed=0;
 items.forEach((ex,i)=>{const done=state.completed.has(ex.id);if(done)completed++;const b=document.createElement('button');b.className='exercise-button'+(!state.play&&state.index===i?' active':'')+(done?' done':'');b.setAttribute('aria-pressed',String(!state.play&&state.index===i));const num=document.createElement('span');num.className='num';num.textContent=done?'✓':String(i+1).padStart(2,'0');const label=document.createElement('span');const title=document.createElement('strong');title.textContent=ex.title;const small=document.createElement('small');small.textContent=ex.skill;label.append(title,small);b.append(num,label);b.onclick=()=>{remember();state.play=false;state.index=i;renderTask();};$('exerciseList').append(b);});
 $('progress').textContent=completed+' / '+items.length;$('playButton').classList.toggle('active',state.play);
}
function renderTask(){
 stop();clearResults();const ex=current();list();$('hint').hidden=true;$('solution').hidden=true;$('hintButton').textContent='✧ Vis et hint';$('solutionButton').textContent='Se løsningsforslag ↗';$('taskKicker').textContent=ex?'ØVELSE '+String(state.index+1).padStart(2,'0'):'DIN FRIE LEGEPLADS';$('skillTag').textContent=ex?ex.skill:'PRØV DIG FREM';$('taskTitle').textContent=ex?ex.title:'Hvad vil du undersøge?';$('taskDescription').textContent=ex?ex.desc:state.studio==='sql'?'Skriv din egen SELECT-forespørgsel på det valgte datasæt. Udforsk tabellerne, forbind dem, og se hvad du finder. Her er der intet facit.':'Afprøv de understøttede Excel-funktioner på datasættet. Vælg pr. række eller én samlet beregning. Her er der intet facit.';
 $('hintButton').hidden=!ex;$('solutionButton').hidden=!ex;$('checkButton').disabled=!ex;$('taskNote').textContent=datasets[state.dataset].source;
 const draft=state.drafts[key()];input().value=draft?draft.text:ex?ex.starter:state.studio==='sql'?(state.dataset==='songs'?'SELECT *\nFROM songs\nLIMIT 10;':'SELECT *\nFROM Invoice\nLIMIT 10;'):'=A2';$('formulaMode').value=draft?.mode||ex?.mode||'rows';updateLines();
 if(ex){$('hint').textContent=ex.hint;$('solutionCode').textContent=ex.answer;$('solutionExplanation').textContent=ex.explain;}
}
function makeTable(headers,rows,{index=false,computed=-1}={}){
 const wrap=document.createElement('div');wrap.className='table-scroll';const table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');
 if(index){const th=document.createElement('th');th.textContent='#';th.className='row-index';tr.append(th);}
 headers.forEach(h=>{const th=document.createElement('th');th.textContent=h;th.scope='col';tr.append(th);});head.append(tr);table.append(head);const body=document.createElement('tbody');rows.forEach((row,i)=>{const tr=document.createElement('tr');if(index){const td=document.createElement('td');td.textContent=i+2;td.className='row-index';tr.append(td);}row.forEach((v,c)=>{const td=document.createElement('td');if(v&&typeof v==='object'&&'error' in v){td.textContent=v.error;td.className='cell-error';td.title=v.error;}else{const raw=v&&typeof v==='object'&&'value' in v?v.value:v;td.textContent=raw===null?'NULL':typeof raw==='number'?fmt.format(raw):typeof raw==='boolean'?(raw?'TRUE':'FALSE'):String(raw??'');if(c===computed)td.className='computed';td.title=String(raw??'NULL');}tr.append(td);});body.append(tr);});table.append(body);wrap.append(table);return wrap;
}
async function renderContext(){
 const ds=datasets[state.dataset];$('schema').replaceChildren();$('schema').className='schema';$('datasetMeta').textContent=ds.meta;$('contextHeading').textContent=state.studio==='sql'?'Databasens tabeller':'Dine kildedata';$('contextTip').innerHTML='<span>↳</span>'+(state.studio==='sql'?'Kig efter fælles ID-felter, når du forbinder tabeller.':'Række 1 er feltnavne. A2 er første datacelle. Her vises de første 8 rækker.');
 if(state.studio==='sql'){
  state.data=null;Object.entries(ds.schema).forEach(([table,fields],i)=>{const details=document.createElement('details');details.open=i===0;const summary=document.createElement('summary');summary.textContent=table;const small=document.createElement('small');const parts=fields.split(' · ');small.textContent=parts.length+' FELTER';summary.append(small);const div=document.createElement('div');div.className='schema-fields';parts.forEach(f=>{const s=document.createElement('span');s.textContent=f;s.className=/\bid\b|Id|artist_id/.test(f)?'pk':'';div.append(s);});details.append(summary,div);$('schema').append(details);});
 }else{
  const id=++state.loadId;state.data=null;$('schema').textContent='Henter kursusdata…';
  try{if(!dataCache[state.dataset]){const res=await fetch(ds.file);if(!res.ok)throw Error();dataCache[state.dataset]=await res.json();}if(id!==state.loadId)return;state.data=dataCache[state.dataset];$('schema').classList.add('source-preview');$('schema').replaceChildren(makeTable(state.data.headers.map((h,i)=>String.fromCharCode(65+i)+' · '+h),state.data.rows.slice(0,8),{index:true}));}catch{if(id===state.loadId)$('schema').textContent='Data kunne ikke hentes. Vælg datasættet igen for at prøve på ny.';}
 }
}
function setStudio(studio){
 remember();stop();state.loadId++;state.studio=studio;state.dataset=studio==='sql'?'songs':'employees';state.index=0;state.play=false;$('sqlTab').classList.toggle('active',studio==='sql');$('excelTab').classList.toggle('active',studio==='excel');$('sqlTab').setAttribute('aria-pressed',studio==='sql');$('excelTab').setAttribute('aria-pressed',studio==='excel');$('crumb').textContent=studio==='sql'?'SQL STUDIO':'EXCEL STUDIO';$('pageTitle').textContent=studio==='sql'?'Fra spørgsmål til forespørgsel.':'En formel. Et resultat. Et aha.';$('pageSubtitle').textContent=studio==='sql'?'Prøv din SQL på rigtige kursusdata, og se resultatet med det samme.':'Afprøv Excel-formler på dine kursusdata — én række eller hele datasættet.';$('engineBadge').textContent=studio==='sql'?'SQLite · i browseren':'22 Excel-funktioner · i browseren';$('editorHeading').textContent=studio==='sql'?'Din forespørgsel':'Din Excel-formel';$('sqlEditorWrap').hidden=studio!=='sql';$('excelEditorWrap').hidden=studio!=='excel';$('dataset').replaceChildren();(studio==='sql'?['songs','chinook']:['employees','payroll']).forEach(id=>{const opt=document.createElement('option');opt.value=id;opt.textContent=datasets[id].name;$('dataset').append(opt);});renderTask();renderContext();
}
function updateLines(){$('lineNumbers').textContent=$('sqlInput').value.split('\n').map((_,i)=>i+1).join('\n');}
function compareRows(actual,ref,ordered){if(actual.length!==ref.length)return false;if(!actual.length)return true;if(actual[0].length!==ref[0].length)return false;if(ordered)return actual.every((row,i)=>row.every((v,j)=>same(v,ref[i][j])));const a=[...actual].sort((x,y)=>JSON.stringify(x).localeCompare(JSON.stringify(y))),b=[...ref].sort((x,y)=>JSON.stringify(x).localeCompare(JSON.stringify(y)));return a.every((row,i)=>row.every((v,j)=>same(v,b[i][j])));}
function run(check=false){
 if(state.working)return;remember();const ex=current();if(check&&!ex)return;
 if(state.studio==='excel'&&!state.data){feedback('Kildedata er ikke klar endnu. Vent et øjeblik, eller vælg datasættet igen.','error');return;}
 if(!input().value.trim()){feedback('Skriv en løsning i editoren først.','error');input().focus();return;}
 stop();state.working=true;$('runButton').disabled=true;$('checkButton').disabled=true;$('runButton').textContent='Arbejder…';$('feedback').hidden=true;
 const worker=new Worker(state.studio==='sql'?'sql-worker.js':'excel-worker.js');state.worker=worker;
 state.timer=setTimeout(()=>{stop();feedback('Beregningen blev stoppet efter 8 sekunder. Afgræns forespørgslen eller formlen, og prøv igen.','error');},8000);
 worker.onerror=()=>{stop();feedback('Beregningsmotoren kunne ikke starte. Genindlæs siden, og prøv igen.','error');};
 worker.onmessage=e=>{const r=e.data;stop();if(!r.ok){feedback(r.error,'error');return;}$('exportButton').disabled=false;$('timing').textContent=r.ms+' ms';
  if(state.studio==='sql'){
   state.last={headers:r.columns,rows:r.rows};$('resultCount').textContent=r.count+' '+(r.count===1?'række':'rækker');$('resultArea').replaceChildren(makeTable(r.columns,r.rows.slice(0,200)));
   $('tableFooter').hidden=false;$('tableFooter').textContent='Viser '+Math.min(r.count,200)+' af '+r.count+' rækker · eksportér CSV for hele resultatet.';
   if(!r.count)feedback('Forespørgslen kørte, men returnerede ingen rækker. Kontrollér dine filtre.');
   if(check){const expected=r.reference;const pass=r.columns.length===expected.columns.length&&compareRows(r.rows,expected.rows,ex.ordered);if(pass){passed(ex);}else{let reason=r.count!==expected.count?'Dit svar har '+r.count+' rækker; det kontrollerede svar har '+expected.count+'.':r.columns.length!==expected.columns.length?'Kontrollér antal og rækkefølge af kolonner.':'Kontrollér værdierne'+(ex.ordered?' og sorteringen':'')+'.';feedback('Ikke helt endnu. '+reason+' Prøv et hint, og kør igen.','error');}}
  }else{
   const summary=$('formulaMode').value==='summary';const resultRows=summary?[[r.results[0]]]:state.data.rows.map((row,i)=>[...row,r.results[i]]);const headers=summary?['Resultat']:[...state.data.headers,'Resultat'];state.last={headers,rows:resultRows.map(row=>row.map(v=>v&&typeof v==='object'?(v.error||v.value):v))};$('resultCount').textContent=r.results.length+' '+(summary?'beregning':'rækker');$('resultArea').replaceChildren(makeTable(headers,resultRows.slice(0,200),{index:!summary,computed:headers.length-1}));$('tableFooter').hidden=false;$('tableFooter').textContent=summary?'Én beregning på det valgte datasæt.':'Formlen er kopieret ned til '+r.results.length+' rækker. Viser de første '+Math.min(200,r.results.length)+'.'+(r.errors?' '+r.errors+' rækker har fejl.':'');
   if(r.errors)feedback(r.errors+' '+(r.errors===1?'række har':'rækker har')+' en formelfejl. Se resultatkolonnen.','error');
   if(check){const pass=$('formulaMode').value===ex.mode&&!r.errors&&r.results.length===r.reference.length&&r.results.every((v,i)=>!r.reference[i].error&&same(v.value,r.reference[i].value));if(pass)passed(ex);else feedback('Ikke helt endnu. '+($('formulaMode').value!==ex.mode?'Vælg '+(ex.mode==='summary'?'én samlet beregning':'beregning pr. række')+'.':r.errors?'Ret formelfejlene i resultatkolonnen.':'Resultaterne matcher ikke det kontrollerede svar på alle rækker.')+' Prøv et hint, og beregn igen.','error');}
  }
 };
 if(state.studio==='sql')worker.postMessage({sql:input().value,database:datasets[state.dataset].file,expected:check?ex.answer:null});
 else worker.postMessage({formula:input().value,data:state.data,mode:$('formulaMode').value,expected:check?ex.answer:null});
}
function passed(ex){state.completed.add(ex.id);persist();list();feedback('✓ Dit resultat matcher det kontrollerede svar. '+(ex.id==='p3'?'Husk at undersøge kildelinjerne med nul timer.':'Kan du også forklare, hvorfor din løsning virker?'),'success');}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(headers,rows){return '\uFEFF'+[headers,...rows].map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';')).join('\r\n');}
$('sqlTab').onclick=()=>{if(state.studio!=='sql')setStudio('sql');};$('excelTab').onclick=()=>{if(state.studio!=='excel')setStudio('excel');};
$('dataset').onchange=()=>{remember();state.dataset=$('dataset').value;state.index=0;state.play=false;renderTask();renderContext();};
$('playButton').onclick=()=>{remember();state.play=true;renderTask();};
$('runButton').onclick=()=>run();$('checkButton').onclick=()=>run(true);
$('hintButton').onclick=()=>{$('hint').hidden=!$('hint').hidden;$('hintButton').textContent=$('hint').hidden?'✧ Vis et hint':'✧ Skjul hint';};
$('solutionButton').onclick=()=>{$('solution').hidden=!$('solution').hidden;$('solutionButton').textContent=$('solution').hidden?'Se løsningsforslag ↗':'Skjul løsningsforslag ↑';};
$('useSolution').onclick=()=>{input().value=current().answer;$('formulaMode').value=current().mode||'rows';remember();updateLines();input().focus();};
$('resetButton').onclick=()=>{stop();delete state.drafts[key()];persist();renderTask();};
$('sqlInput').oninput=()=>{updateLines();remember();};$('formulaInput').oninput=remember;$('formulaMode').onchange=()=>{stop();remember();clearResults();};
for(const el of [$('sqlInput'),$('formulaInput')])el.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();run();}if(e.key==='Tab'){e.preventDefault();el.setRangeText('  ',el.selectionStart,el.selectionEnd,'end');updateLines();remember();}});
$('sqlInput').onscroll=()=>{$('lineNumbers').scrollTop=$('sqlInput').scrollTop;};
$('exportButton').onclick=()=>{if(state.last)download(new Blob([csv(state.last.headers,state.last.rows)],{type:'text/csv;charset=utf-8'}),'accounting-lab-resultat.csv');};
$('downloadButton').onclick=()=>{const ds=datasets[state.dataset];if(state.studio==='sql'){const a=document.createElement('a');a.href=ds.file;a.download=state.dataset==='songs'?'songs.db':'Chinook_Sqlite.sqlite';a.click();}else if(state.data)download(new Blob([csv(state.data.headers,state.data.rows)],{type:'text/csv;charset=utf-8'}),state.dataset+'.csv');};
$('helpButton').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();$('startHelp').onclick=()=>$('helpDialog').close();$('helpDialog').addEventListener('click',e=>{if(e.target===$('helpDialog')){const r=$('helpDialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('helpDialog').close();}});
['songs','chinook'].forEach(id=>{const opt=document.createElement('option');opt.value=id;opt.textContent=datasets[id].name;$('dataset').append(opt);});
renderTask();renderContext();
